function promptScore(prompt) {
  let score = 0;
  if (prompt.length > 20) score += 30;
  if (/error|stack|expected|should/i.test(prompt)) score += 30;
  if (/function|component|route|query/i.test(prompt)) score += 20;
  if (/\?|how|what|why|fix/i.test(prompt)) score += 20;
  return score;
}
const score = promptScore('Fix my code');
console.log('score: ' + score);
console.log(score < 50 ? 'too vague — add context' : 'good prompt');

